import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Deploy the Online judging service","description":"","frontmatter":{"sourcePath":"docs/backend/service.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/backend/service.md","alternateUrl":"/TCSExam/docs/zh/backend/service/","alternateAnchors":{"deploy-the-online-judging-service":"deploy-the-online-judging-service","install":"install","configure":"configure","start-and-check":"start-and-check","configuration-reference":"configuration-reference","behavior-contract":"behavior-contract","security-boundaries":"security-boundaries","troubleshooting":"troubleshooting","writing-a-platform-adapter":"writing-a-platform-adapter","testing-and-verification":"testing-and-verification"}},"headers":[],"relativePath":"backend/service/index.md","filePath":"backend/service/index.md"}'),o={name:"backend/service/index.md"};function d(r,e,n,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="deploy-the-online-judging-service" tabindex="-1">Deploy the Online judging service <a class="header-anchor" href="#deploy-the-online-judging-service" aria-label="Permalink to &quot;Deploy the Online judging service&quot;">​</a></h1><p>This guide covers service configuration, operation and platform adapters. It is for operators hosting Online Solver judging.</p><p>The service manages HTTP requests, judge sessions, parallel workers, feedback, archives and submission counts. Select the bundled Docker adapter for a local Docker host, or implement the platform adapter interface for another runtime. Operators provide the execution hosts, judge images and service credentials.</p><p>For a local Docker deployment, follow the <a href="/TCSExam/docs/backend/docker/">generated configuration workflow</a>. The <a href="/TCSExam/docs/solver-backend/">HTTP protocol reference</a> defines client requests and responses.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[runtime,backend]&#39;</span></span></code></pre></div><h2 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h2><p>For a manually configured service, copy the example and set credentials in the service environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/backend/config.example.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/backend.yaml</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TCSEXAM_TOKEN_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> the</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> identity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TCSEXAM_TOKEN_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> the</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TCSEXAM_ARCHIVE_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> the</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> verifier-only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p>Start from <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/backend/config.example.yaml" target="_blank" rel="noreferrer">config.example.yaml</a>, a Docker example whose commented values show the defaults. Secrets come from the environment first (<code>TCSEXAM_TOKEN_ID</code>, <code>TCSEXAM_TOKEN_SECRET</code>, <code>TCSEXAM_ARCHIVE_TOKEN</code>, <code>TCSEXAM_WORKER_GROUP</code>) and override the YAML values; keep real tokens out of committed files. <code>TCSEXAM_DOCKER_SOCKET</code> overrides the Docker socket path.</p><p><code>public_base_url</code> deserves attention: the agent inside each judge worker dials <code>&lt;public_base_url&gt;/v1/tunnel/{app}</code>, so it must be an address the judge workers can reach. It defaults to <code>http://127.0.0.1:&lt;port&gt;</code>, which works for local testing with the bundled test adapter. The Docker example explicitly uses <code>http://host.docker.internal:8420</code>; the Docker adapter rejects a container-loopback URL on a non-host worker network. See the <a href="/TCSExam/docs/backend/docker/#host-requirements">Docker networking and host requirements</a>.</p><p>Keep the archive credential exclusive to the verifier. Confirm that the worker callback address is reachable and that the selected images are prepared before starting the service.</p><h2 id="start-and-check" tabindex="-1">Start and check <a class="header-anchor" href="#start-and-check" aria-label="Permalink to &quot;Start and check&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/backend.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # validate config + load the adapter</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/backend.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # run the service</span></span></code></pre></div><p><code>check</code> prints the effective configuration as JSON and loads the configured adapter. It exits 0 on success and 2 on any configuration problem (including an empty <code>adapter</code> or an adapter that fails to load), so it is safe to wire into deployment pipelines. <code>serve</code> accepts <code>--host</code> / <code>--port</code> overrides. <code>python -m tcsexam.backend --config build/backend.yaml</code> is an equivalent entry point.</p><h2 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h2><p>Reading the tables: every value is the built-in default, applied when the key is absent from the YAML. Keys marked &quot;env&quot; are overridden by the environment variable of the same name when set.</p><p>Top-level keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>host</code></td><td><code>0.0.0.0</code></td><td>Bind address of the HTTP service</td></tr><tr><td><code>port</code></td><td><code>8420</code></td><td>Bind port</td></tr><tr><td><code>public_base_url</code></td><td><code>&quot;&quot;</code> (falls back to <code>http://127.0.0.1:&lt;port&gt;</code>)</td><td>Externally reachable base URL; in-worker agents dial <code>&lt;public_base_url&gt;/v1/tunnel/{app}</code></td></tr><tr><td><code>auth.token_id</code></td><td>empty</td><td>Shared-token auth id (env <code>TCSEXAM_TOKEN_ID</code>); both empty = unauthenticated, local testing only</td></tr><tr><td><code>auth.token_secret</code></td><td>empty</td><td>Shared-token auth secret (env <code>TCSEXAM_TOKEN_SECRET</code>)</td></tr><tr><td><code>auth.additional_tokens</code></td><td><code>[]</code></td><td>Extra accepted (id, secret) pairs for graceful rotation</td></tr><tr><td><code>auth.run_id_mode</code></td><td><code>warn</code></td><td>Caller-identity enforcement: <code>warn</code> logs and serves, <code>required</code> rejects with 400, <code>off</code> does not read the header</td></tr><tr><td><code>state_dir</code></td><td><code>/tmp/tcsexam-backend-state</code></td><td>Session journal, archives, persisted payloads</td></tr><tr><td><code>adapter</code></td><td><code>&quot;&quot;</code></td><td>Platform adapter spec: <code>docker</code>, <code>module:factory</code>, or <code>local-test</code> for testing only; empty = the service refuses to create sessions with a clear error</td></tr><tr><td><code>docker_socket</code></td><td><code>/var/run/docker.sock</code></td><td>Local Docker Engine Unix socket (env <code>TCSEXAM_DOCKER_SOCKET</code>); remote TCP endpoints are rejected</td></tr><tr><td><code>docker_network</code></td><td><code>bridge</code></td><td>Docker network for judge workers; <code>public_base_url</code> must be reachable from it</td></tr><tr><td><code>docker_pull_missing_images</code></td><td><code>true</code></td><td>Pull a missing judge image, using the full creation budget; private images should be pulled by the operator</td></tr><tr><td><code>docker_host_gateway</code></td><td><code>true</code></td><td>Add <code>host.docker.internal:host-gateway</code> to workers for the Docker-host tunnel address</td></tr><tr><td><code>docker_api_timeout_seconds</code></td><td><code>60</code></td><td>Ordinary Docker API call timeout; cold image pulls use the full creation budget instead</td></tr><tr><td><code>worker_group</code></td><td><code>tcsexam</code></td><td>Worker-group tagging prefix (env <code>TCSEXAM_WORKER_GROUP</code>); empty = no group tagging. When a session is created with a run-id, EVERY shard&#39;s worker creation carries <code>labels={run_id, token_id}</code> and <code>group_name=&quot;&lt;worker_group&gt;--&lt;run-id slug&gt;&quot;</code> (the platform can reap exactly one attempt&#39;s workers); sessions without a run-id are created untagged</td></tr><tr><td><code>archive_token</code></td><td><code>&quot;&quot;</code></td><td>Verifier-only credential (env <code>TCSEXAM_ARCHIVE_TOKEN</code>) for archive/payload, hidden-session creation, every creation carrying <code>judge_payload</code>, and session list/reconciliation queries; empty disables those operations</td></tr><tr><td><code>public_image_map</code></td><td><code>{}</code></td><td>Exact map from a client-requested original judge image to its public-only worker image. Public creation fails closed with 403 when this is empty or the requested image is absent; hidden creation never uses the map</td></tr></tbody></table><p><code>backend</code> section (worker creation and global usage caps):</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>create_retries</code></td><td><code>20</code></td><td>Extra creation attempts after the first failure, transient errors only</td></tr><tr><td><code>create_retry_delay_seconds</code></td><td><code>60</code></td><td>Base delay between creation retries; attempt N waits base x 2^(N-1), capped at 10 min</td></tr><tr><td><code>create_concurrency</code></td><td><code>64</code></td><td>Upper bound on concurrent worker creations</td></tr><tr><td><code>session_create_concurrency</code></td><td><code>64</code></td><td>Per-session creation concurrency, taken before the global gate</td></tr><tr><td><code>max_sandboxes_global</code></td><td><code>4096</code></td><td>Global worker-count pre-check at create accept time</td></tr><tr><td><code>max_sandbox_memory_mb</code></td><td><code>32768000</code></td><td>Memory dimension (MiB) of the same pre-check</td></tr><tr><td><code>ready_timeout_seconds</code></td><td><code>2400</code></td><td>Platform-side creation/readiness budget handed to the adapter</td></tr></tbody></table><p><code>backend.judge_sessions</code> section (the main knobs; the example file comments the rest):</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>max_sessions</code></td><td><code>16</code></td><td>Global live-session cap; creates beyond it fail as transient</td></tr><tr><td><code>profile</code></td><td><code>&quot;&quot;</code></td><td>Opaque scheduling hint passed to the adapter as-is</td></tr><tr><td><code>spec</code></td><td><code>{cpu_count: 4, memory_mb: 8192, storage_mb: 20480}</code></td><td>Per-worker resources handed to the adapter verbatim</td></tr><tr><td><code>command</code></td><td><code>python3 /judge/judge_worker.py</code></td><td>Judge worker started inside the worker; empty = the agent only relays to an already-running server</td></tr><tr><td><code>judge_port</code></td><td><code>8082</code></td><td>Port the in-worker judge server listens on</td></tr><tr><td><code>ttl_seconds</code></td><td><code>21600</code></td><td>Default per-session TTL (platform safety net)</td></tr><tr><td><code>max_ttl_seconds</code></td><td><code>46800</code></td><td>Clamp for caller-requested TTL</td></tr><tr><td><code>idle_ttl_seconds</code></td><td><code>14400</code></td><td>Idle-reap threshold; must exceed the longest single judge request</td></tr><tr><td><code>ready_timeout_seconds</code></td><td><code>1800</code></td><td>Create + boot budget before the tunnel wait fails</td></tr><tr><td><code>max_shards</code></td><td><code>512</code></td><td>Upper bound on <code>n_shards</code> per session</td></tr><tr><td><code>min_ready_ratio</code></td><td><code>1.0</code></td><td>Degraded-ready floor; 1.0 = partial provisioning fails the whole session rather than producing a partial score</td></tr><tr><td><code>hibernate_enabled</code></td><td><code>true</code></td><td>Recycle settled, quiet sessions to metadata-only and re-provision on the next submit</td></tr><tr><td><code>hibernate_grace_seconds</code></td><td><code>1800</code></td><td>Quiet period before a settled session hibernates</td></tr><tr><td><code>submission_cap.enabled</code></td><td><code>false</code></td><td>Per-session submission cap (opt-in); counting always runs for reconciliation visibility</td></tr><tr><td><code>submission_cap.default</code></td><td><code>10</code></td><td>Cap per judging session</td></tr><tr><td><code>submission_cap.overrides</code></td><td><code>{}</code></td><td>Per-image-family cap; a family hit beats the default</td></tr><tr><td><code>routes</code></td><td><code>[]</code></td><td>Per-image-family readiness/lifecycle budgets; first <code>image_contains</code> substring match wins. <code>ready_timeout_seconds</code> drives tunnel wait and agent startup; <code>create_ready_timeout_seconds</code> goes to the adapter. <code>ttl_seconds</code> supplies the default when the caller omits TTL; <code>idle_ttl_seconds</code> sets that session&#39;s idle threshold. Explicit requested TTL takes precedence and still obeys <code>max_ttl_seconds</code>. Routed values survive hibernation and wake-up.</td></tr></tbody></table><p>The primary <code>auth.token_id</code> and <code>auth.token_secret</code> must both be non-empty strings. Omit both to disable authentication for a local test. A partial or empty pair fails configuration validation. Each <code>additional_tokens</code> entry must contain exactly two non-empty strings, and rotation credentials require a primary pair: workers use the primary credentials to connect their tunnels. Validation runs after environment overrides when loading YAML and again when building the application; errors name the invalid field without printing its value. Credential comparison accepts Unicode and uses constant-time byte comparison for both elements of every pair.</p><p>Concurrent creates share a provisioning session only with an explicit <code>X-TCSEXAM-Client-Id</code> and identical effective inputs: token identity, validated run-id, effective worker image (after public mapping), uploaded file names and contents, resources, lifetime, shard count and instance set. Omitting default resources or lifetime is equivalent to passing the same defaults explicitly. A changed input creates a separate session; it cannot silently reuse a worker containing another upload.</p><p>Session lifetime, worker startup and request reading are separate budgets. The shipped development clients request 46800 seconds (12 hours plus one hour of margin); the default <code>max_ttl_seconds</code> is also 46800. The public sharded store starts the service-side lifetime when the group becomes ready, while the platform worker lifetime starts at worker creation. Startup time therefore consumes some platform margin. Hibernation releases workers and a later submission provisions new ones; it retains submission history and renews the service-side lifetime at readiness. Final-evaluation clients create separate sessions and retain their per-task 14400–28800 second lifetimes. Reducing <code>max_ttl_seconds</code> clamps either client&#39;s request and can expire an active session before its budget is used; allow both judging time and startup margin in the platform configuration.</p><p><code>ready_timeout_seconds</code> bounds the tunnel connection wait. The worker agent uses the same startup budget, capped at 7200 seconds, in both single-worker and sharded creation. Per-image <code>create_ready_timeout_seconds</code> goes to the platform adapter. <code>read_timeout_seconds</code> (default 7200) bounds an upstream judge response and is forwarded to every worker agent. For a long judging request, increase its read timeout and the corresponding fan-out timeout; increasing session lifetime alone does not increase these request limits.</p><h2 id="behavior-contract" tabindex="-1">Behavior contract <a class="header-anchor" href="#behavior-contract" aria-label="Permalink to &quot;Behavior contract&quot;">​</a></h2><p>These semantics are fixed by the task clients and covered by tests; a deployment must not change them.</p><ul><li>A submission is counted once, when accepted. <code>POST /v1/judge/sessions/{id}/submit</code> returns an integer submission number after accepting the body. The counting unit is the relay-level <code>/submit</code>; shard fan-out is judging-internal parallelism and never counts.</li><li>HTTP 429 on <code>/submit</code> means the per-session submission cap, with body <code>{&quot;error&quot;: &quot;submission_cap_exceeded&quot;, &quot;cap&quot;: ..., &quot;used&quot;: ...}</code>. The verifier interprets 429 as the cap, so the backend must not use it for ordinary worker congestion.</li><li>HTTP 503 (<code>error_class=transient</code>) means the submission was not accepted and can be retried. It covers still-provisioning sessions and global-capacity rejections. Transient messages carry the marker &quot;please try again&quot;, which the task-side retry matchers match verbatim.</li><li>HTTP 410 (or <code>error_class=terminal</code> in a JSON body) means the session is permanently destroyed.</li><li>DELETE destroys every worker and closes every service-side reverse tunnel belonging to the session, including every shard. A late reconnection using the destroyed session&#39;s one-shot app name is rejected with 404; ordinary tunnel drops still allow reconnection. The retained archive and the creation/submission payload history remain readable by the verifier after the session status becomes 410.</li><li>Infrastructure failures never produce a valid zero score. With the default <code>min_ready_ratio: 1.0</code>, partial provisioning fails the whole session; a failed provisioning never accepted a submission, so the caller&#39;s submission budget is untouched.</li><li>Tasks with one shared time pool across instances must be created with <code>n_shards=1</code> — the whole instance set on one worker. Sharding a pool task would change its judging semantics. The shipped clients already encode this.</li><li>The archive credential (<code>X-TCSEXAM-Archive-Token</code>) is presented by the verifier alone. It gates archive and payload downloads, hidden-session creation (including an omitted <code>instance_set</code>, which defaults to hidden), every public or hidden creation carrying <code>judge_payload</code>, and every session list/reconciliation query. Missing, wrong and unconfigured credentials are rejected before any worker is created or session data is returned. Archive and payload endpoints retain their uniform-404 contract; the create and list gates answer 403.</li><li>Public self-test sessions (<code>instance_set=public</code>) without <code>judge_payload</code> need only the service token pair. Their status, submission and result-polling paths do not use the archive credential. Public creation requires an exact <code>public_image_map</code> entry and uses its public-only value as the session and worker image. An empty map or unregistered requested image answers 403 before session registration or worker creation; there is no fallback to the original image. Hidden creation never applies the map. Public sessions are journaled for history but never count against the submission cap.</li><li>Sessions are owned by the run that created them. The effective run-id (<code>X-TCSEXAM-Run-Id</code>, validated by the auth middleware) is stored on the session and journaled, so it survives DELETE and service restarts. Every session-level endpoint — status, relay (<code>/submit</code>, <code>/submissions</code>, and any forwarded tail), DELETE, archive, the three payload endpoints, and the <code>?session_ids=</code> reconciliation query — serves only requests whose run-id matches the session&#39;s owner. A mismatch answers exactly like an unknown session id: the uniform 404 (<code>unknown judge session {sid}</code>), never a 401/403 and never the 410 destroyed shape, so the check does not leak whether the session exists; in the <code>?session_ids=</code> answer a mismatched sid reports <code>present=false</code> with its counts withheld. Sessions returned by the ordinary list and <code>?client_ip=</code> diagnostic query obey the same ownership filter, including retained destroyed sessions; the diagnostic query&#39;s total includes only visible rows. DELETE of an unknown session answers the same 404 as a wrong run, while repeated DELETE by the owner of a known released session stays 200 and returns <code>stopped=false</code>, including after journal replay. The <code>/v1/status</code> route remains a service-wide operations view with global statistics. Sessions created without a run-id are unowned and unrestricted (local and legacy callers that never send run-ids keep working). Creation dedup keys on the run-id too: two runs never share a provisioning session even when they send the same <code>X-TCSEXAM-Client-Id</code>, while one run&#39;s concurrent retry still shares.</li></ul><h2 id="security-boundaries" tabindex="-1">Security boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security boundaries&quot;">​</a></h2><ul><li>Use a service token pair for authenticated deployments and inject it through the environment. Store real credentials outside the source repository.</li><li>Give the archive token only to the verifier. It authorizes hidden-session creation, session reconciliation and archive access; keep it out of model environments, workers and submission relays.</li><li>Run-Id is a caller-supplied attempt label. For mutually untrusted callers, provide independently authenticated per-attempt credentials or an equivalent authorization layer in addition to the shared-token service.</li><li>Map public sessions to images containing only public data. Review every retained image layer using the <a href="/TCSExam/docs/backend/public-images/">public-image guide</a>; select the public judging mode after separating the image contents.</li><li>Give the Docker socket only to the backend process. It controls the host and must remain outside model containers and judge workers.</li><li>Keep platform credentials inside the adapter configuration and exclude them from logs, worker environments and exception messages.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom or deployment condition</th><th>Action</th></tr></thead><tbody><tr><td>Docker admission or quota check fails</td><td>Check the effective CPU, memory and configured storage quota in the <a href="/TCSExam/docs/backend/docker/#host-requirements">Docker host guide</a>.</td></tr><tr><td>A worker remains after the service stopped</td><td>Restart the service to recover its managed workers, or inspect and remove only the identified owned container. Expiry handling runs in the backend process.</td></tr><tr><td>A custom or older worker gets HTTP 400 with <code>run_id_mode=required</code></td><td>Send its owning <code>X-TCSEXAM-Run-Id</code> on the tunnel connection. Keep <code>warn</code> during a mixed-version upgrade and update worker agents before enabling <code>required</code>.</td></tr><tr><td>A long evaluation loses its session</td><td>Allow the requested lifetime and startup margin in <code>max_ttl_seconds</code>; also check request read timeouts in the configuration reference.</td></tr><tr><td>Selecting <code>local-test</code></td><td>Use it only for backend development tests. Its workers are local temporary directories with no resource limits or isolation.</td></tr></tbody></table><h2 id="writing-a-platform-adapter" tabindex="-1">Writing a platform adapter <a class="header-anchor" href="#writing-a-platform-adapter" aria-label="Permalink to &quot;Writing a platform adapter&quot;">​</a></h2><p>The full contract is the module docstring of <code>tcsexam.backend.adapter</code>. A minimal, annotated skeleton ships at <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/backend/examples/adapter_minimal.py" target="_blank" rel="noreferrer">examples/adapter_minimal.py</a>.</p><p>Reading the table: these are the members the session stores call. The loader verifies all of them at startup; a missing member is a configuration error, never a silent degradation.</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Contract</th></tr></thead><tbody><tr><td><code>ready_timeout_seconds</code></td><td>attribute <code>float</code></td><td>The adapter&#39;s own creation budget, read by the store&#39;s provisioning-deadline math</td></tr><tr><td><code>create_sandbox</code></td><td><code>(profile, image_url, *, ttl_seconds, spec, ready_timeout_seconds, group_name, labels) -&gt; Worker</code></td><td>Create one worker from <code>image_url</code> with exactly the requested resources</td></tr><tr><td><code>register_long_lived</code></td><td><code>(app_name, worker) -&gt; None</code></td><td>Put a worker on the long-lived table (the tunnel-close reaper and <code>stop_app</code> work through it)</td></tr><tr><td><code>sandbox_for_app</code></td><td><code>(app_name) -&gt; Worker | None</code></td><td>The live long-lived worker for an app, no state change</td></tr><tr><td><code>long_lived_count</code> / <code>long_lived_memory_mb</code></td><td><code>() -&gt; int</code></td><td>Long-lived table size and total memory, for usage accounting</td></tr><tr><td><code>stop_app</code></td><td><code>async (app_name) -&gt; None</code></td><td>Destroy a long-lived worker; idempotent, unknown app = no-op</td></tr></tbody></table><p>The worker surface the stores use:</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Contract</th></tr></thead><tbody><tr><td><code>worker.ctrl.write_bytes</code></td><td><code>async (path, data: bytes, parents=False) -&gt; None</code></td><td>Write bytes inside the worker; <code>parents=True</code> creates missing directories</td></tr><tr><td><code>worker.ctrl.run</code></td><td><code>async (cmd, shell=False, text=False, timeout=30)</code></td><td>Run a command inside the worker; returns an object with a <code>stdout</code> attribute. Raise on transport failure; a non-zero exit code is reported, not raised</td></tr><tr><td><code>worker.ctrl.read_text</code></td><td><code>async (path) -&gt; str</code></td><td>Read a text file; raises when missing or unreadable</td></tr><tr><td><code>worker.name</code></td><td>attribute <code>str</code></td><td>Platform-side identifier, used in logs only</td></tr><tr><td><code>worker.delete</code></td><td><code>async () -&gt; None</code></td><td>Destroy the worker; idempotent, best-effort (the worker&#39;s own TTL is the final safety net)</td></tr><tr><td><code>worker.resources</code></td><td>optional attribute <code>WorkerResources</code></td><td>The creation-time resources. Not required: <code>BasePlatformAdapter</code> prefers it for the <code>long_lived_memory_mb</code> accounting and otherwise falls back to the resources its own <code>create_sandbox</code> recorded</td></tr></tbody></table><p>Behavior rules every implementation must keep:</p><ul><li>Honor the requested image and resources as given. If the platform cannot provide them, raise a clear error. Silently booting a smaller worker is a contract violation: judging runs assume the declared resources.</li><li>Error classification is by class name. Names in <code>errors.NON_TRANSIENT_ERROR_NAMES</code> (<code>AuthenticationError</code>, <code>PermissionDeniedError</code>, <code>InvalidArgumentError</code>, <code>InsufficientCreditsError</code>, <code>JudgeBootError</code>) are never retried; every other exception is treated as transient and retried with exponential backoff. <code>ValueError</code> is always non-transient (a caller bug).</li><li><code>stop_app</code> and <code>worker.delete()</code> are idempotent.</li><li>Cleanup is scoped: only ever destroy resources the adapter itself created, never account-wide purges.</li><li>A cancelled creation must not leak a half-created worker.</li><li>Platform credentials live in the adapter&#39;s own configuration and must never appear in logs, worker environment variables, or exception messages — exception text propagates to task clients.</li></ul><p>Subclassing <code>BasePlatformAdapter</code> provides the transient-retry loop under a creation concurrency gate, the long-lived table, and an idempotent <code>stop_app</code> with agent.log tail recovery; you then implement only <code>_create_worker</code>, one creation attempt against your platform.</p><p>Loading: <code>adapter: docker</code> selects the bundled Docker implementation described in the <a href="/TCSExam/docs/backend/docker/">Docker guide</a>. For another platform, set <code>adapter</code> to a <code>module:factory</code> spec. The factory is imported, called with the loaded <code>Config</code> when it accepts one positional argument (otherwise with no arguments), and the result is checked for the full surface above. An empty <code>adapter</code> fails at startup with a <code>ConfigurationError</code> — the service never falls back to a test double silently. The explicit value <code>local-test</code> selects the bundled local-process test adapter (testing only; its &quot;workers&quot; are temp directories on the service machine, with no isolation and no resource enforcement).</p><p>Self-check any adapter against the bundled contract suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.backend.contracttest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --adapter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mypackage.cloud:make_adapter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry.example.com/your-judge:1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-profile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.backend.contracttest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --adapter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry.example.com/your-judge:1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.backend.contracttest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --adapter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local-test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # exercise the test double</span></span></code></pre></div><p>The suite prints one line per check and exits 0 when all pass, 1 when any check fails, 2 when the adapter cannot be loaded. It creates real resources through the adapter and destroys every worker it creates — point it at a test environment. The checks are platform-neutral: creation honoring the request verbatim, unique worker identity, file preparation, status diagnostics, command start, memory accounting, idempotent stop/delete, creation-failure cleanup, and scoped cleanup.</p><p><code>--image</code> and <code>--profile</code> select what the checks pass to <code>create_sandbox</code>. Pass an available image and the profile your platform expects. The defaults (<code>registry.example.com/contract-judge:1</code> / <code>contract-profile</code>) are examples for the local test adapter.</p><h2 id="testing-and-verification" tabindex="-1">Testing and verification <a class="header-anchor" href="#testing-and-verification" aria-label="Permalink to &quot;Testing and verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/tcsexam/backend/tests/</span></span></code></pre></div><p>The suite exercises HTTP requests, sharding, submission accounting, archives, run ownership, lifecycle and adapter behavior. Docker unit tests use a simulated Engine over a Unix socket. To exercise actual worker creation and cleanup, run the <a href="#writing-a-platform-adapter">adapter contract suite</a> with an available image and platform profile. See <a href="/TCSExam/docs/contributing/">contributing</a> for the complete source checks.</p>`,51)])])}const k=t(o,[["render",d]]);export{u as __pageData,k as default};
